import {mountGenes,geneRates,referenceGenes} from './genes.js';
import {profiles,referenceRates,createRun,replaceBath,stepRun,poolStats,balanceError} from './isotope-model.js';
export function mountIsotopeLab(root){
 let selected='glucose',volume=1,oxygen=.2,scenario='reference';
 const make=()=>Object.fromEntries(Object.keys(profiles).map(id=>[id,{experiment:createRun(id),reference:createRun(id)}]));let runs=make();
 root.innerHTML=`<div class="membrane-header"><div><span class="section-number">NEW</span><h2>Compare your results</h2><span class="membrane-subtitle">Experiment alongside a matched reference</span></div></div><div class="isotope-toolbar"><label>Cell comparison <select id="iso-scenario"><option value="reference">Reference / normal-like hypothesis</option><option value="tumour">Tumour metabolism · exploratory</option><option value="custom">Custom perturbation</option></select></label><label>Expression proxy · exploratory <input id="iso-expression" type="range" min="0" max="4" step="0.1" value="1"><output id="iso-expression-value">1.0×</output></label><span id="iso-scenario-note">Reference rates, not a validated healthy cell.</span></div><div class="isotope-toolbar"><label>Carrier / isotope pair <select id="iso-profile">${Object.entries(profiles).map(([id,p])=>`<option value="${id}">${p.element} · ${p.title}</option>`).join('')}</select></label><label>Heavy isotope in pulse <input id="iso-enrichment" type="number" min="0" max="100" step="1" value="99"> %</label><button id="iso-pulse">Add another pulse to both</button><button id="iso-chase">Wash out label in both</button><button id="iso-reference">Restore reference genes</button><button id="iso-reset">Clear this tracer pair</button><button id="iso-export">Export comparison CSV</button></div><details class="tracer-details"><summary>Calculated transport rates · controlled by genes</summary><div class="isotope-toolbar">${['transport','processing','storage'].map(k=>`<label>${k} <select id="iso-${k}"><option value="0">Blocked</option><option value="0.25">0.25×</option><option value="1" selected>Reference · 1×</option><option value="4">4×</option></select></label>`).join('')}<span>Only the experiment receives rate changes. Storage is unused in the glucose profile.</span></div></details><p id="iso-description" class="isotope-copy"></p><div id="iso-paired-cells" class="iso-paired-cells" aria-label="Isotope composition comparison"></div><div class="isotope-table-wrap"><table class="isotope-table"><thead><tr><th>Pool</th><th>Total element<br>µM equivalent</th><th id="iso-heavy-head">Heavy</th><th id="iso-light-head">Light</th><th>Heavy fraction<br>experiment / reference</th><th>Heavy : light</th><th>Δ total vs reference</th></tr></thead><tbody id="iso-rows"></tbody></table></div><div class="isotope-plots"><div><h3>Experiment vs reference</h3><label>Metric <select id="iso-metric"><option value="fraction">Heavy isotope fraction</option><option value="total">Total element · µM equivalent</option><option value="heavy">Heavy isotope · µM equivalent</option></select></label><label>Pool <select id="iso-pool"></select></label><svg id="iso-chart" viewBox="0 0 520 170" role="img" aria-label="Heavy isotope fraction in experiment and reference"></svg><p id="iso-chart-legend">Solid green: experiment · dashed amber: reference.</p><label><input id="iso-overlay" type="checkbox" checked> Show isotope tones in the 3D cell</label><p id="iso-overlay-legend"></p></div><div><h3>Reference protocol</h3><p>Same carrier, starting pools and isotope pulse. Reference transport, processing and storage remain at 1×; reference cell volume is V₀ and oxygen is 0.200 mM.</p><p>Experiment concentrations respond to cell volume. Only glucose’s lumped oxidation rate also responds to the main oxygen control. Other cell controls do not directly alter these illustrative rates.</p><p id="iso-status" role="status"></p></div></div><details class="tracer-details"><summary>How to interpret these results</summary><p>The expression slider is a hypothetical linear rate multiplier for glucose/glutamine transport and processing, not a gene-expression measurement. It has no transcriptional delay or protein dynamics. The tumour scenario is a qualitative sensitivity experiment: glucose and glutamine transport and processing coefficients become 4×. It is not a MYC expression model, a normal/cancer classifier or a fitted tumour cell line. Other carriers remain unchanged because no oncogene links have been implemented. The normal-like reference is the same generic model at 1×. Scenario changes preserve pools and time; reset a pair before starting a fresh comparison.</p><p>Initial pools contain 100 (bath), 20 (mobile) and 10 (each remaining pool) µmol of tracked element per litre of reference-cell volume. These are invented comparison amounts, not physiological concentrations. All intracellular readouts divide by whole-cell volume V/V₀; membrane values are equivalent inventory densities, not concentrations within the lipid bilayer. Bath uses a fixed reference volume. CO₂ is a collected inventory, not dissolved concentration.</p><p>Pulse replaces the bath at unchanged total amount with the selected heavy fraction; chase replaces it with the starting isotope mix. Removed and added atoms are accounted separately. There is a finite bath, no maintained nutrient supply, and the reference trajectory need not be stationary. Natural fractions use representative NIST abundances, renormalized to the displayed two-isotope pair when other isotopes exist. They are not full natural isotope compositions.</p><p>Every transfer moves heavy and light atoms proportionally, with no assumed isotope-dependent kinetics. Profiles have different illustrative pathways and coefficients; those coefficients are hypotheses, not fitted biological measurements. This is an atom ledger, not a molecular isotopologue solver: M+0…M+n distributions, positional labels and full reaction chemistry are not yet resolved. U labels describe the selected input; the solver retains only marginal heavy/light atom counts.</p><p>Glucose-derived carbon passing to CO₂ is displayed separately from ATP: this module does not add ATP to the main model. Cholesterol trafficking does not yet change membrane stiffness. Nitrogen and sulfur incorporation and metal-binding pools are coarse-grained proxies. For evidence and methodology: <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4879607/" target="_blank" rel="noopener noreferrer">carbon/nitrogen tracing in human cells</a>; <a href="https://pml.nist.gov/cgi-bin/Compositions/stand_alone.pl?ascii=ascii" target="_blank" rel="noopener noreferrer">NIST isotope compositions</a>.</p><div id="iso-equations"></div></details>`;
 root.querySelectorAll('.isotope-toolbar')[0].hidden=true;
 const $=id=>root.querySelector('#'+id),format=v=>Number(v).toFixed(3);
 function sample(run,vol){run.history.push({genes:genes.get(),time:run.time,volume:vol,oxygen:run === runs[run.id].reference ? .2 : oxygen,rates:{...run.rates},heavy:[...run.heavy],light:[...run.light],inH:run.inH,inL:run.inL,outH:run.outH,outL:run.outL});}
 function select(){const p=profiles[selected],s=runs[selected].experiment;$('iso-profile').value=selected;for(const k of Object.keys(referenceRates)){const input=$('iso-'+k);if(![...input.options].some(o=>Number(o.value)===s.rates[k]))input.add(new Option(s.rates[k].toFixed(1)+'×',s.rates[k]));input.value=s.rates[k];}$('iso-pool').innerHTML=p.names.map((n,i)=>`<option value="${i}" ${i===2?'selected':''}>${n}</option>`).join('');$('iso-description').textContent=p.note;$('iso-heavy-head').textContent=p.pair[0]+p.element+' · µM equivalent';$('iso-light-head').textContent=p.pair[1]+p.element+' · µM equivalent';$('iso-equations').textContent='Illustrative first-order rates (s⁻¹): '+p.edges.map(([a,b,k,type])=>`${p.names[a]} → ${p.names[b]}: ${k} × ${type}`).join('; ')+'.';render();}
 function render(){const p=profiles[selected],{experiment:e,reference:r}=runs[selected];$('iso-rows').innerHTML=p.names.map((name,i)=>{const v=i===0||name.includes('collected')?1:volume,a=poolStats(e,i,v),b=poolStats(r,i);return `<tr><th>${name}</th><td>${format(a.total)}</td><td>${format(a.heavy)}</td><td>${format(a.light)}</td><td>${(100*a.fraction).toFixed(2)}% / ${(100*b.fraction).toFixed(2)}%</td><td>${a.ratio===null?'∞':format(a.ratio)}</td><td>${format(a.total-b.total)}</td></tr>`;}).join('');
 const i=Number($('iso-pool').value),end=Math.max(120,e.time),start=Math.max(0,end-120),metric=$('iso-metric').value;
 const val=d=>{const total=d.heavy[i]+d.light[i],v=i===0||p.names[i].includes('collected')?1:d.volume;return metric==='fraction'?(total?100*d.heavy[i]/total:0):metric==='heavy'?d.heavy[i]/v:total/v;};
 const visible=[...e.history,...r.history].filter(d=>d.time>=start);const max=metric==='fraction'?100:Math.max(1,...visible.map(val))*1.1;
 const poly=s=>s.history.filter(d=>d.time>=start).map(d=>`${(35+470*(d.time-start)/120).toFixed(2)},${(140-120*val(d)/max).toFixed(2)}`).join(' ');
 $('iso-chart').innerHTML=`<path d="M35 20V140H505" fill="none" stroke="#a5b1aa"/><text x="2" y="24">${max.toFixed(1)}</text><text x="12" y="144">0</text><text x="35" y="163">${start.toFixed(0)} s</text><text x="455" y="163">${end.toFixed(0)} s</text><polyline points="${poly(r)}" fill="none" stroke="#ad824c" stroke-width="3" stroke-dasharray="6 4"/><polyline points="${poly(e)}" fill="none" stroke="#355d49" stroke-width="2"/>`;
 $('iso-chart-legend').textContent='Solid green: experiment · dashed amber: reference · '+(metric==='fraction'?'heavy isotope %':'µM element-equivalent');
 const f=poolStats(e,i).fraction;$('iso-paired-cells').innerHTML=[[e,'Experiment'],[r,'Reference · 1×']].map(([run,label])=>{const q=poolStats(run,i);return `<div><strong>${label}</strong><div class="iso-composition-disc" style="background:conic-gradient(#193b4c ${100*q.fraction}%,#e9eff3 0)" role="img" aria-label="${label}: ${(100*q.fraction).toFixed(1)} percent heavy isotope"></div><span>${(100*q.fraction).toFixed(1)}% heavy · ${p.names[i]}</span></div>`;}).join('');$('iso-overlay-legend').textContent=`Dark: ${p.pair[0]}${p.element} (${(100*f).toFixed(1)}%) · light: ${p.pair[1]}${p.element}. 100 display markers encode composition, not atom count or concentration. Selected pool: ${p.names[i]}.`;
 $('iso-status').textContent=`${e.active?'Running on the cell clock':'Ready: start a pulse'} · elapsed ${e.time.toFixed(1)} s · maximum atom-balance error ${Math.max(balanceError(e),balanceError(r)).toExponential(1)} µM × V₀. Changing carrier preserves other runs.`;
 }
 function dose(chase){const raw=Number($('iso-enrichment').value);if(!chase&&(!Number.isFinite(raw)||raw<0||raw>100||$('iso-enrichment').value==='')){$('iso-enrichment').reportValidity();return;}const f=chase?profiles[selected].fraction:raw/100;for(const [key,s] of Object.entries(runs[selected])){replaceBath(s,f);sample(s,key==='reference'?1:volume);}render();}
 $('iso-profile').onchange=()=>{selected=$('iso-profile').value;genes.setCarrier(selected);select();};$('iso-pool').onchange=render;$('iso-metric').onchange=render;$('iso-pulse').onclick=()=>dose(false);$('iso-chase').onclick=()=>dose(true);
 for(const k of Object.keys(referenceRates))$('iso-'+k).onchange=()=>{const s=runs[selected].experiment;s.rates[k]=Number($('iso-'+k).value);scenario='custom';$('iso-scenario').value=scenario;$('iso-scenario-note').textContent='Custom rate perturbation; no cell-type calibration.';sample(s,volume);render();};
 function expression(value){$('iso-expression').value=value;$('iso-expression-value').textContent=value.toFixed(1)+'×';for(const id of ['glucose','glutamine']){const s=runs[id].experiment;s.rates={transport:value,processing:value,storage:1};sample(s,volume);}scenario=value===1?'reference':'custom';$('iso-scenario').value=scenario;select();$('iso-scenario-note').textContent='Expression-to-rate hypothesis: glucose/glutamine transport and processing = slider × baseline. Reference stays 1×. Not a measured MYC effect; other elements have no gene coupling.';}
 $('iso-expression').oninput=()=>expression(Number($('iso-expression').value));
 $('iso-scenario').onchange=()=>{scenario=$('iso-scenario').value;if(scenario==='custom')return;$('iso-expression').value=scenario==='tumour'?4:1;$('iso-expression-value').textContent=scenario==='tumour'?'4.0×':'1.0×';for(const [id,pair] of Object.entries(runs)){pair.experiment.rates={...referenceRates};if(scenario==='tumour'&&['glucose','glutamine'].includes(id))pair.experiment.rates={transport:4,processing:4,storage:1};sample(pair.experiment,volume);}select();$('iso-scenario-note').textContent=scenario==='tumour'?'Hypothesis only: glucose/glutamine transport and processing 4×. Other carriers unchanged; no universal cancer signature or fitted MYC/KRAS effect.':'Reference rates, not a validated healthy cell.';};
 function restore(){genes.reset(false);$('iso-expression').value=1;$('iso-expression-value').textContent='1.0×';scenario='reference';$('iso-scenario').value=scenario;$('iso-scenario-note').textContent='Reference rates restored; state and history retained.';for(const pair of Object.values(runs)){pair.experiment.rates={...referenceRates};sample(pair.experiment,volume);}select();}
 $('iso-reference').onclick=restore;$('iso-reset').onclick=()=>{runs[selected]={experiment:createRun(selected),reference:createRun(selected)};applyGenes(genes.get());select();};
 $('iso-export').onclick=()=>{const rows=['carrier,run,time_s,pool,heavy_mass,light_mass,heavy_amount_uM_V0,light_amount_uM_V0,volume_V0,oxygen_mM,transport,processing,storage,added_heavy,added_light,removed_heavy,removed_light,MYC_expression,KRAS_expression,KRAS_oncogenic,p53_activity,p53_loss'];for(const [id,pair] of Object.entries(runs))for(const [kind,s] of Object.entries(pair)){sample(s,kind==='reference'?1:volume);for(const d of s.history)for(let i=0;i<s.heavy.length;i++)rows.push([id,kind,d.time,profiles[id].names[i],...profiles[id].pair,d.heavy[i],d.light[i],i===0||profiles[id].names[i].includes('collected')?1:d.volume,d.oxygen,...Object.values(d.rates),d.inH,d.inL,d.outH,d.outL,...Object.values(kind==='reference'?referenceGenes():d.genes)].join(','));}const url=URL.createObjectURL(new Blob([rows.join('\r\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='cellula-paired-isotope-experiments.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 const genes=mountGenes(document.getElementById('gene-panel'),(g,restart=false,carrier=null)=>{if(carrier)selected=carrier;if(restart){runs[selected]={experiment:createRun(selected),reference:createRun(selected)};}applyGenes(g);if(restart)dose(false);select();if(restart){document.dispatchEvent(new Event("cellula-comparison-start"));root.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"start"});}});
 function applyGenes(g){const rates=geneRates(g);for(const [id,pair] of Object.entries(runs)){pair.experiment.rates=rates[id]||{...referenceRates};sample(pair.experiment,volume);}for(const k of Object.keys(referenceRates))$('iso-'+k).disabled=true;$('iso-scenario-note').textContent='Controlled by Cell identity & genes.';}
 applyGenes(genes.get());select();return {visual(){const p=profiles[selected],s=runs[selected].experiment,i=Number($('iso-pool').value);return {enabled:$('iso-overlay').checked,fraction:poolStats(s,i).fraction,label:`${p.title} · ${p.names[i]}`,location:i===0||p.names[i].includes('collected')?'outside':selected==='cholesterol'&&i===2?'membrane':'inside'};},step(dt,cellVolume,cellOxygen){volume=cellVolume;oxygen=cellOxygen;for(const pair of Object.values(runs)){stepRun(pair.experiment,dt,oxygen);stepRun(pair.reference,dt,.2);for(const [kind,s] of Object.entries(pair))if(s.active&&(!s.history.length||s.time-s.history.at(-1).time>=.5))sample(s,kind==='reference'?1:volume);}},render,restore,reset(){genes.reset(false);runs=make();volume=1;oxygen=.2;$('iso-expression').value=1;$('iso-expression-value').textContent='1.0×';scenario='reference';$('iso-scenario').value=scenario;$('iso-scenario-note').textContent='Reference rates, not a validated healthy cell.';select();}};
}
